import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.Cms9CC3y.js";const i="/entislng/v5/assets/e559e9c64767e524-20261015000321-16asjif.CzfuVqIA.png",p=JSON.parse('{"title":"气相计算功能开启说明","description":"","frontmatter":{"title":"气相计算功能开启说明","date":"2026-10-14T16:03:21.000Z","lastmod":"2026-11-24T18:47:00.000Z"},"headers":[],"relativePath":"guide/1273.md","filePath":"guide/帮助文档/专项说明/气相计算功能开启说明.md"}'),n={name:"guide/1273.md"};function s(l,a,d,_,h,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="气相计算功能开启说明" tabindex="-1">气相计算功能开启说明 <a class="header-anchor" href="#气相计算功能开启说明" aria-label="Permalink to &quot;气相计算功能开启说明&quot;">​</a></h1><p>‍</p><h4 id="第一步-要开启气相计算的开关-默认并没有开启-会跳过气相的计算" tabindex="-1">第一步:要开启气相计算的开关,默认并没有开启,会跳过气相的计算 <a class="header-anchor" href="#第一步-要开启气相计算的开关-默认并没有开启-会跳过气相的计算" aria-label="Permalink to &quot;第一步:要开启气相计算的开关,默认并没有开启,会跳过气相的计算&quot;">​</a></h4><p>操作说明：点击选择目标罐，然后点击右键或上部工具栏中选择 &quot;罐实时参数配置&quot;，显示如下窗体，选择 &quot;罐计算参数配置&quot;，勾选 &quot;是否气相校正&quot;，再点击应用保存：</p><h4 id="第二步-配置气相计算需要的基础参数" tabindex="-1">第二步:配置气相计算需要的基础参数 <a class="header-anchor" href="#第二步-配置气相计算需要的基础参数" aria-label="Permalink to &quot;第二步:配置气相计算需要的基础参数&quot;">​</a></h4><p>基础参数分为 2 种方式：是否使用摩尔参数或液相气相比，此参数主要根据产品配置。</p><h6 id="如使用摩尔参数计算-请选择摩尔质量法-然后输入摩尔值-如使用气相液相比计算-则输入相应的气相-液相比-然后点击确定保存" tabindex="-1">如使用摩尔参数计算，请选择摩尔质量法，然后输入摩尔值，如使用气相液相比计算，则输入相应的气相/液相比，然后点击确定保存 <a class="header-anchor" href="#如使用摩尔参数计算-请选择摩尔质量法-然后输入摩尔值-如使用气相液相比计算-则输入相应的气相-液相比-然后点击确定保存" aria-label="Permalink to &quot;如使用摩尔参数计算，请选择摩尔质量法，然后输入摩尔值，如使用气相液相比计算，则输入相应的气相/液相比，然后点击确定保存&quot;">​</a></h6><h4 id="第三步-添加气相计算需要的输入基础数据" tabindex="-1">第三步：添加气相计算需要的输入基础数据 <a class="header-anchor" href="#第三步-添加气相计算需要的输入基础数据" aria-label="Permalink to &quot;第三步：添加气相计算需要的输入基础数据&quot;">​</a></h4><p>气相计算主要的输入基础数据为气相压力和气相温度，主要在仪表配置中配置相关的数据的读取项。</p><h4 id="最后-打开相应罐的单罐图-即可显示气相计算相关值" tabindex="-1">最后，打开相应罐的单罐图，即可显示气相计算相关值 <a class="header-anchor" href="#最后-打开相应罐的单罐图-即可显示气相计算相关值" aria-label="Permalink to &quot;最后，打开相应罐的单罐图，即可显示气相计算相关值&quot;">​</a></h4><p><img src="'+i+'" alt=""></p>',11)])])}const q=e(n,[["render",s]]);export{p as __pageData,q as default};
